const patient = $json.patient_name;
const service = $json.service;
const date = $json.appointment_date;
const time = $json.appointment_time;
const clinicName = $json.clinic_name;
const clinicAddr = $json.clinic_address;
const clinicPhone = $json.clinic_phone;

const subject = `Appointment Confirmed — ${service} at ${clinicName}`;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head><body style="font-family: -apple-system, BlinkMacSystemFont, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;"><div style="background: #f8f9fa; border-radius: 8px; padding: 30px;"><h1 style="color: #2d3748; margin-top: 0;">Appointment Confirmed ✓</h1><p style="color: #4a5568; font-size: 16px;">Hi ${patient},</p><p style="color: #4a5568;">Your appointment has been confirmed. Here are the details:</p><table style="width: 100%; border-collapse: collapse; margin: 20px 0;"><tr><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; font-weight: bold; color: #2d3748;">Service</td><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; color: #4a5568;">${service}</td></tr><tr><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; font-weight: bold; color: #2d3748;">Date</td><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; color: #4a5568;">${date}</td></tr><tr><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; font-weight: bold; color: #2d3748;">Time</td><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; color: #4a5568;">${time}</td></tr><tr><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; font-weight: bold; color: #2d3748;">Location</td><td style="padding: 10px; border-bottom: 1px solid #e2e8f0; color: #4a5568;">${clinicAddr}</td></tr></table><div style="background: #fff; border-left: 4px solid #4299e1; padding: 15px; margin: 20px 0; border-radius: 4px;"><p style="margin: 0; color: #2d3748; font-weight: bold;">Need to reschedule?</p><p style="margin: 5px 0 0; color: #4a5568;">Reply to this email or call us at ${clinicPhone}</p></div><p style="color: #718096; font-size: 14px; margin-top: 30px;">— ${clinicName}</p></div></body></html>`;

return [{json: { ...$json, email_subject: subject, email_html_body: html }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const slotName = $json.slot_name;

// Increment email quota
await fetch(`${supabaseUrl}/rest/v1/rpc/fn_increment_email_quota`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ p_clinic_id: clinicId, p_slot_name: slotName })
});

// Mark provider success
await fetch(`${supabaseUrl}/rest/v1/rpc/fn_mark_provider_success`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ p_clinic_id: clinicId, p_provider_name: slotName })
});

// Audit log
await fetch(`${supabaseUrl}/rest/v1/audit_log`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: clinicId, event_type: 'email_sent', payload: { slot_used: slotName, to: $json.patient_email } })
});

return [{json: { success: true, slot_used: slotName }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const failedSlot = $json.slot_name;
const retryCount = ($json.retry_count || 0) + 1;

// Mark provider failure
await fetch(`${supabaseUrl}/rest/v1/rpc/fn_mark_provider_failure`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ p_clinic_id: clinicId, p_provider_name: failedSlot, p_error: $json.error?.message || 'Send failed' })
});

// Try to pick next slot
const res = await fetch(`${supabaseUrl}/rest/v1/rpc/fn_pick_email_slot`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ p_clinic_id: clinicId })
});
const nextSlot = await res.json();

if (!nextSlot || retryCount >= 4) {
  return [{json: { ...$json, all_failed: true, retry_count: retryCount }}];
}

return [{json: { ...$json, slot_name: nextSlot, retry_count: retryCount, all_failed: false }}];

const supabaseUrl = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;

// Insert into DLQ
await fetch(`${supabaseUrl}/rest/v1/dead_letter_queue`, {
  method: 'POST',
  headers: { 'apikey': key, 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ clinic_id: $json.clinic_id, workflow_name: 'WF-3', payload: { patient_email: $json.patient_email, subject: $json.email_subject }, error_message: 'All email providers exhausted', status: 'pending', retry_count: 0, max_retries: 3 })
});

// Telegram alert
await fetch(`https://api.telegram.org/bot${$env.TELEGRAM_ADMIN_BOT_TOKEN}/sendMessage`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: $env.TELEGRAM_ADMIN_CHAT_ID, text: `\u26a0 All email slots exhausted for clinic ${$json.clinic_id}. Email queued in DLQ.` })
});

return [{json: { success: false, reason: 'all_slots_exhausted' }}];
